const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=n=>Number(n||0).toLocaleString('ko-KR')+'원';
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const shops=[
  {id:'bake',name:'오후의 빵집',image:'croissant',lat:37.5445,lng:127.0433,address:'성수동 가상 골목 12'},
  {id:'cafe',name:'모퉁이 커피',image:'coffee',lat:37.5438,lng:127.0421,address:'성수동 가상 골목 18'},
  {id:'rice',name:'소담한 식탁',image:'rice',lat:37.5441,lng:127.0407,address:'성수동 가상 골목 24'}
];
const samples=[
  [1,'bake','딸기 크루아상',4500,10,'croissant','바삭한 크루아상에 달콤한 오후 한 조각'],
  [2,'cafe','아메리카노',3000,30,'coffee','고소하고 부드러운 오늘의 원두'],
  [3,'rice','소담 채소 덮밥',8500,15,'rice','채소 듬뿍, 든든한 한 끼'],
  [4,'bake','버터 스콘',3500,12,'scone','겉은 바삭, 속은 촉촉'],
  [5,'cafe','오렌지 주스',4000,20,'orange','커피 대신 상큼한 한 잔'],
  [6,'rice','꼬마 주먹밥',2000,24,'onigiri','산책길에 쏙, 아이와 함께'],
  [7,'bake','오늘의 샌드위치',6500,8,'sandwich','싱싱한 채소를 넉넉하게'],
  [8,'cafe','카페라테',4500,25,'latte','고소한 우유와 에스프레소'],
  [9,'rice','에그 샐러드',5500,10,'egg','가벼운 한 끼도 정성 가득']
].map(([id,shop,name,price,stock,image,desc])=>({id,shop,name,price,stock,image:'assets/'+image+'.jpg',desc,closing:'18:00',date:day(),likes:0,sample:true}));
const home={lat:37.5446,lng:127.0445};
const saved=(()=>{try{return JSON.parse(localStorage.getItem('hangolmok-v2')||'null')}catch{return null}})();
const old=(()=>{try{return JSON.parse(localStorage.getItem('hangolmok-v1')||'null')}catch{return null}})();
let state=saved||{mode:'guest',tab:'feed',font:1,menus:old?.menus?.length?old.menus.map(m=>({...m,closing:m.closing||'18:00',sample:!m.custom})):samples,likes:old?.liked||[],orders:[],cart:[],location:null,locationStatus:'demo'};
state.menus=Array.isArray(state.menus)?state.menus:samples;
state.likes=Array.isArray(state.likes)?state.likes:[];
state.orders=Array.isArray(state.orders)?state.orders:[];
state.cart=Array.isArray(state.cart)?state.cart:[];
state.font=Number(state.font)||1;
if(!state.menus.some(m=>m.date===day())){state.menus=samples;state.cart=[];}
let leafletMap=null;let feedQuery='',mapQuery='',aiText='',aiResult=null,draft=null,photo=null,selectedShop=null,recognition=null;
const persist=()=>{try{localStorage.setItem('hangolmok-v2',JSON.stringify(state))}catch{toast('이 기기의 저장 공간이 부족합니다.')}};
const shop=id=>shops.find(s=>s.id===id)||shops[0];
const active=()=>state.menus.filter(m=>m.date===day());
const image=m=>esc(m.image||'assets/croissant.jpg');
const distance=(a,b)=>{const r=Math.PI/180,x=(b.lat-a.lat)*r,y=(b.lng-a.lng)*r,z=Math.sin(x/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(y/2)**2;return 6371*2*Math.atan2(Math.sqrt(z),Math.sqrt(1-z))};
const center=()=>state.location||home;
const nearby=()=>shops.filter(s=>distance(center(),s)<=3);
const nearbyMenus=()=>active().filter(m=>nearby().some(s=>s.id===m.shop));
const hhmm=d=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(d);
const icon=(name)=>({feed:'▦',map:'⌖',orders:'▤',register:'＋',manage:'≡',heart:'♡'}[name]||'•');
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3300)}
function say(t){if(!window.speechSynthesis){toast('이 브라우저는 음성 안내를 지원하지 않습니다.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ko-KR';u.rate=.9;speechSynthesis.speak(u)}
function pageSpeech(){
 const titles={feed:'피드',map:'지도',orders:'내 주문',register:'등록',manage:'관리'};
 const parts=[titles[state.tab]+' 화면입니다.'];
 if(state.tab==='feed'){const items=visibleFeed();parts.push('근처 메뉴 '+items.length+'개.');parts.push(...items.slice(0,6).map(m=>shop(m.shop).name+'의 '+m.name+', '+won(m.price)+', 재고 '+m.stock+'개.'))}
 if(state.tab==='map'){const list=visibleMapShops();parts.push('반경 3킬로미터 내 가게 '+list.length+'곳.');parts.push(...list.map(s=>s.name+', 약 '+distance(center(),s).toFixed(1)+'킬로미터.'))}
 if(state.tab==='orders'){parts.push('주문 '+state.orders.length+'건.');parts.push(...state.orders.slice(0,3).map(o=>'픽업 대기 주문, '+won(o.total)+', '+o.stops.length+'곳 픽업.'))}
 if(state.tab==='register')parts.push('먼저 사진을 촬영하거나 올리고, 상품의 이름, 가격, 재고량, 마감 시간을 말해 주세요. 초안을 확인한 다음 등록할 수 있습니다.');
 if(state.tab==='manage'){parts.push('오늘의 메뉴 '+active().length+'개.');parts.push(...active().slice(0,6).map(m=>m.name+', '+won(m.price)+', 재고 '+m.stock+'개.'))}
 say(parts.join(' '))
}
function render(){document.documentElement.style.setProperty('--scale',state.font);const owner=state.mode==='owner';const tabs=owner?[['register','등록'],['manage','관리']]:[['feed','피드'],['map','지도'],['orders','내 주문']];if(!tabs.some(([id])=>id===state.tab))state.tab=owner?'register':'feed';
 $('#app').innerHTML=`<div class="site"><header class="site-header"><div class="header-main"><button class="brand" data-action="home" aria-label="한 골목, 한 메뉴 홈"><span class="brand-mark">ㅎ</span><span>한 골목, 한 메뉴</span></button><button class="mode-switch" data-action="mode">${owner?'손님 ver':'사장 ver'} <span aria-hidden="true">↗</span></button></div><div class="header-tools"><div class="font-tools" aria-label="글자 크기 조절"><span>글자 크기</span><button data-action="font-down" aria-label="글자 작게">가−</button><button data-action="font-up" aria-label="글자 크게">가＋</button></div><button class="voice-btn" data-action="speak" aria-label="현재 화면 음성 안내">◖)) <span>음성 안내</span></button></div></header><main id="main" class="main ${state.tab}">${content()}</main><nav class="tabbar" aria-label="${owner?'사장님 메뉴':'손님 메뉴'}">${tabs.map(([id,label])=>`<button data-action="tab" data-value="${id}" class="${state.tab===id?'active':''}" aria-current="${state.tab===id?'page':'false'}"><span class="tab-icon" aria-hidden="true">${icon(id)}</span><span>${label}</span></button>`).join('')}</nav></div>`;if(state.tab==='map')requestAnimationFrame(initMap)}
function heading(kicker,title,sub=''){return `<div class="page-heading"><span class="kicker">${kicker}</span><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function content(){return ({feed:feedPage,map:mapPage,orders:ordersPage,register:registerPage,manage:managePage})[state.tab]()}
function locationNote(){return `<div class="location-note"><span>⌖ ${state.locationStatus==='live'?'내 위치 기준':'성수동 예시 위치 기준'} · 반경 3km</span><button data-action="locate">${state.locationStatus==='live'?'위치 새로고침':'내 위치 사용'}</button></div>`}
function visibleFeed(){return nearbyMenus().filter(m=>(m.name+' '+m.desc+' '+shop(m.shop).name).toLocaleLowerCase().includes(feedQuery.toLocaleLowerCase()))}
function card(m){const s=shop(m.shop),liked=state.likes.includes(m.id),inCart=state.cart.some(x=>x.id===m.id);return `<article class="post"><div class="post-top"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${esc(s.address)} · ${distance(center(),s).toFixed(1)}km</small></span><span class="stock ${m.stock?'':'sold'}">${m.stock?'재고 '+m.stock+'개':'품절'}</span></div><img class="post-photo" src="${image(m)}" alt="${esc(m.name)} 사진" loading="lazy"><div class="post-actions"><button data-action="like" data-id="${m.id}" class="${liked?'liked':''}" aria-pressed="${liked}" aria-label="${esc(m.name)} 좋아요">${liked?'♥':'♡'} <span>${(m.likes||0)+(liked?1:0)}</span></button><button data-action="add" data-id="${m.id}" class="add-btn" ${!m.stock?'disabled':''}>${inCart?'한 개 더 담기':'담기 ＋'}</button></div><div class="post-info"><div class="title-line"><h2>${esc(m.name)}</h2><strong>${won(m.price)}</strong></div><p>${esc(m.desc)}</p><small>마감 ${esc(m.closing||'18:00')} · ${m.sample?'샘플 메뉴':'사장님 등록 메뉴'}</small></div></article>`}
function feedPage(){return `<div class="feed-head"><div>${heading('TODAY IN YOUR ALLEY','오늘의 골목 피드','근처 메뉴를 사진 한 장씩 둘러보세요.')}</div><button class="ai-button" data-action="ai-open">✧ AI 세트</button></div><label class="search-field"><span aria-hidden="true">⌕</span><input id="feed-search" type="search" placeholder="원하는 메뉴나 가게 검색" value="${esc(feedQuery)}" aria-label="메뉴 검색"></label>${locationNote()}<div class="feed-list">${visibleFeed().map(card).join('')||`<div class="empty"><h2>표시할 메뉴가 없어요</h2><p>${state.locationStatus==='live'?'현재 위치에서 3km 이내의 등록된 샘플 가게가 없습니다.':'검색어를 바꾸거나 내 위치를 확인해 주세요.'}</p></div>`}</div>${state.cart.length?`<button class="floating-cart" data-action="cart">담은 메뉴 ${state.cart.reduce((n,x)=>n+x.qty,0)}개 · ${won(cartTotal())} <span>보기 →</span></button>`:''}<p class="demo-note">가상 가게와 샘플 메뉴를 사용하는 시연 화면입니다. 가격과 재고는 이 기기에만 저장됩니다.</p>`}
function visibleMapShops(){return nearby().filter(s=>{const q=mapQuery.toLocaleLowerCase();return !q||s.name.toLocaleLowerCase().includes(q)||active().some(m=>m.shop===s.id&&m.name.toLocaleLowerCase().includes(q))})}
function mapPage(){const c=center(),markers=visibleMapShops().map(s=>{const x=50+(s.lng-c.lng)*750,y=50-(s.lat-c.lat)*750;return `<button class="map-pin" data-action="shop" data-value="${s.id}" style="left:${Math.max(9,Math.min(91,x))}%;top:${Math.max(12,Math.min(87,y))}%" aria-label="${esc(s.name)} 정보">●<span>${esc(s.name)}</span></button>`}).join('');return `${heading('AROUND ME','내 주변 지도','현재 위치에서 반경 3km 안의 가게를 찾아보세요.')}<label class="search-field"><span aria-hidden="true">⌕</span><input id="map-search" type="search" placeholder="지도에서 메뉴 검색" value="${esc(mapQuery)}" aria-label="지도 메뉴 검색"></label>${locationNote()}<div class="map-canvas" role="group" aria-label="내 위치와 근처 가게를 표시한 안내 지도"><div class="street horizontal h1"></div><div class="street horizontal h2"></div><div class="street horizontal h3"></div><div class="street vertical v1"></div><div class="street vertical v2"></div><div class="street diagonal"></div><div class="radius-ring"></div><div id="leaflet-map" class="leaflet-map"></div><div class="you-pin" style="left:50%;top:50%" title="내 위치 또는 예시 위치">⌖<span>내 위치</span></div>${markers}<span class="map-attrib">위치 관계 안내 · 실제 지도 아님</span></div><div class="map-list"><h2>3km 이내 가게 <span>${visibleMapShops().length}곳</span></h2>${visibleMapShops().map(s=>`<button data-action="shop" data-value="${s.id}" class="shop-row"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${distance(c,s).toFixed(1)}km · 오늘 메뉴 ${active().filter(m=>m.shop===s.id).length}개</small></span><b>›</b></button>`).join('')||'<p class="muted">반경 안에 표시할 샘플 가게가 없습니다.</p>'}</div><p class="demo-note">가게 위치는 성수동 가상 주소를 사용합니다. 실제 길찾기 지도는 추후 연결됩니다.</p>`}
function ordersPage(){const likedShops=[...new Set(active().filter(m=>state.likes.includes(m.id)).map(m=>m.shop))];return `${heading('MY ALLEY','내 주문','주문 현황과 좋아하는 가게를 확인하세요.')}<section class="panel"><div class="panel-title"><h2>주문 현황</h2><span>${state.orders.length}건</span></div>${state.orders.length?state.orders.map(orderCard).join(''):'<div class="empty small"><h3>아직 주문이 없어요</h3><p>피드에서 메뉴를 담아 주문 흐름을 체험해 보세요.</p><button class="plain-button" data-action="tab" data-value="feed">피드로 가기 →</button></div>'}</section><section class="panel"><div class="panel-title"><h2>좋아요 남긴 가게</h2><span>${likedShops.length}곳</span></div>${likedShops.length?likedShops.map(id=>{const s=shop(id);return `<button class="shop-row" data-action="shop" data-value="${id}"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>좋아요 남긴 메뉴 ${active().filter(m=>m.shop===id&&state.likes.includes(m.id)).length}개</small></span><b>›</b></button>`}).join(''):'<p class="muted">좋아요를 누른 가게가 여기에 모여요.</p>'}</section><section class="panel review-panel"><h2>다녀온 골목, 어땠나요?</h2><p>방문 경험을 남기는 리뷰 기능은 추후 제공됩니다.</p><button class="outline-button" data-action="review">리뷰 작성하기</button></section>`}
function orderCard(o){return `<div class="order-card"><div class="order-top"><strong>주문 #${String(o.id).slice(-6)}</strong><span>픽업 대기 · 데모</span></div><p>${o.items.map(i=>esc(i.name)+' × '+i.qty).join(' · ')}</p><strong>${won(o.total)}</strong><div class="order-bottom"><small>${esc(o.date)} · ${o.stops.length}곳 픽업</small><button data-action="route" data-id="${o.id}">픽업 순서 보기 →</button></div></div>`}
function registerPage(){return `${heading('FOR SHOP OWNERS','오늘의 메뉴 등록','사진과 말 한마디로 상품 등록 초안을 만드세요.')}<div class="step-label"><span>01 사진</span><span>02 음성 설명</span><span>03 확인 후 등록</span></div><section class="panel register-panel"><h2>1. 상품 사진</h2><p>사진을 촬영하거나 기기에서 올려 주세요.</p><label class="upload-box"><input id="product-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" aria-label="상품 사진 촬영 또는 업로드">${photo?`<img src="${photo}" alt="선택한 상품 사진"><strong>사진을 선택했어요 · 다시 선택 가능</strong>`:'<span class="camera-icon">▣</span><strong>촬영 또는 사진 올리기</strong><small>JPG, PNG, WebP · 최대 5MB</small>'}</label><h2>2. 상품 설명</h2><p>예: “딸기 크루아상 4,500원, 10개 남았고 오후 6시에 마감해요.”</p><div class="voice-input"><button data-action="dictate" class="mic-button" aria-label="음성 입력 시작">🎙 <span>음성으로 입력</span></button><span id="mic-status">마이크가 어려우면 아래에 직접 입력해 주세요.</span></div><textarea id="product-phrase" rows="4" placeholder="상품 이름, 가격, 재고량, 마감시간을 말하거나 입력하세요."></textarea><label class="form-label">가게<select id="product-shop">${shops.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><button class="primary" data-action="make-draft">등록 초안 만들기 →</button><p class="demo-note">현재 입력 분석은 규칙 기반 데모입니다. 추출 결과를 사장님이 확인하고 수정한 뒤 등록합니다.</p></section>`}
function managePage(){return `${heading('FOR SHOP OWNERS','등록 메뉴 관리','가격과 남은 수량을 바로 수정하세요.')}<div class="panel"><div class="panel-title"><h2>오늘의 메뉴</h2><span>${active().length}개</span></div>${active().map(m=>`<div class="manage-item"><img src="${image(m)}" alt=""><div><strong>${esc(m.name)}</strong><small>${esc(shop(m.shop).name)} · ${won(m.price)} · 재고 ${m.stock}개</small></div><button class="outline-button" data-action="edit" data-id="${m.id}">수정</button></div>`).join('')||'<p class="muted">오늘 등록된 메뉴가 없습니다.</p>'}</div><p class="demo-note">수정한 내용은 현재 브라우저에 저장됩니다.</p>`}
function overlay(title,body){$('#overlay').innerHTML=`<div class="overlay-bg"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button data-action="close" aria-label="닫기">✕</button></div>${body}</section></div>`;document.body.classList.add('modal-open');$('.sheet button,.sheet input,.sheet textarea')?.focus()}
function close(){recognition?.stop();recognition=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open')}
function shopInfo(id){const s=shop(id);selectedShop=id;overlay(esc(s.name),`<img class="sheet-cover" src="assets/${s.image}.jpg" alt=""><div class="info-line">⌖ ${esc(s.address)} · ${distance(center(),s).toFixed(1)}km</div><p class="muted">가게 상세 정보는 추후 제작됩니다.</p><h3>오늘의 메뉴</h3>${active().filter(m=>m.shop===id).map(m=>`<div class="mini-item"><span>${esc(m.name)}</span><strong>${won(m.price)}</strong></div>`).join('')}<button class="primary" data-action="close">닫기</button>`)}
function cartTotal(){return state.cart.reduce((n,x)=>n+(active().find(m=>m.id===x.id)?.price||0)*x.qty,0)}
function cartPage(){const rows=state.cart.map(x=>{const m=active().find(m=>m.id===x.id);return m?`<div class="cart-row"><img src="${image(m)}" alt=""><span><strong>${esc(m.name)}</strong><small>${won(m.price)} · ${esc(shop(m.shop).name)}</small></span><div class="quantity"><button data-action="qty" data-id="${m.id}" data-value="-1" aria-label="${esc(m.name)} 수량 줄이기">−</button><b>${x.qty}</b><button data-action="qty" data-id="${m.id}" data-value="1" aria-label="${esc(m.name)} 수량 늘리기">＋</button></div></div>`:''}).join('');overlay('담은 메뉴',`${rows||'<p class="muted">담은 메뉴가 없습니다.</p>'}<div class="cart-total"><span>합계</span><strong>${won(cartTotal())}</strong></div><p class="muted">가상 상품의 주문 흐름 시연입니다. 결제와 실제 주문 전송은 이루어지지 않습니다.</p><button class="primary" data-action="order" ${!state.cart.length?'disabled':''}>데모 주문 확정 · 픽업 순서 보기</button>`)}
function pickupStops(items){const ids=[...new Set(items.map(i=>i.shop))],remaining=shops.filter(s=>ids.includes(s.id)),stops=[];let pos=center();while(remaining.length){remaining.sort((a,b)=>distance(pos,a)-distance(pos,b));const s=remaining.shift();stops.push({...s,km:distance(pos,s)});pos=s}const now=Date.now();let minutes=10;return stops.map((s,i)=>{minutes+=Math.max(5,Math.ceil(s.km*12));return {id:s.id,name:s.name,address:s.address,km:s.km,pickup:hhmm(new Date(now+minutes*60000)),items:items.filter(x=>x.shop===s.id).map(x=>x.name+' × '+x.qty)}})}
function order(){if(!state.cart.length)return;const items=[];for(const x of state.cart){const m=active().find(m=>m.id===x.id);if(!m||m.stock<x.qty){toast('재고가 변경되었습니다. 수량을 확인해 주세요.');cartPage();return}items.push({id:m.id,shop:m.shop,name:m.name,qty:x.qty,price:m.price})}const total=cartTotal();items.forEach(i=>active().find(m=>m.id===i.id).stock-=i.qty);const o={id:Date.now(),date:day()+' '+hhmm(new Date()),items,total,stops:pickupStops(items)};state.orders.unshift(o);state.cart=[];persist();close();state.mode='guest';state.tab='orders';render();route(o.id)}
function route(id){const o=state.orders.find(x=>x.id===Number(id));if(!o)return;overlay('픽업 순서와 예상 시간',`<p class="muted">현재 위치에서 가까운 순서로 안내합니다. 예상 시간은 준비 10분과 도보 속도 기준이며 실제 상황에 따라 달라집니다.</p><div class="route-stops">${o.stops.map((s,i)=>`<div class="route-stop"><span class="step-circle">${i+1}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.address)}</small><p>${s.items.map(esc).join(' · ')}</p></div><b>${esc(s.pickup)} 예상</b></div>`).join('')}</div><p class="demo-note">데모 주문입니다. 실제 구매·결제·픽업 예약은 발생하지 않습니다.</p><button class="primary" data-action="close">확인</button>`)}
function parseKoreanAmount(t){const n=t.match(/(\d[\d,]*)\s*(만|천)?\s*원/);if(!n)return null;return Number(n[1].replace(/,/g,''))*(n[2]==='만'?10000:n[2]==='천'?1000:1)}
function parseWish(t){const people=Number(t.match(/(\d+)\s*명/)?.[1]||1);const budget=parseKoreanAmount(t)||20000;return {people:Math.max(1,Math.min(10,people)),budget,coffee:!/커피(?:는|를|가)?\s*(빼|제외|없이)|카페인(?:은|을)?\s*(빼|제외|없이)/.test(t),keywords:t}}
function recommend(t){const wish=parseWish(t),pool=nearbyMenus().filter(m=>m.stock>0&&(!wish.coffee?!/커피|라테|아메리카노/.test(m.name):true));const meal=/밥|식사|든든|점심|저녁/.test(t),sweet=/디저트|빵|달콤/.test(t);const rank=m=>(meal?/밥|샌드위치|샐러드/.test(m.name)?5:0:0)+(sweet?/빵|스콘|크루아상/.test(m.name)?5:0:0)+(m.shop==='rice'?2:0);pool.sort((a,b)=>rank(b)-rank(a)||a.price-b.price);let left=wish.budget,chosen=[];for(let round=0;round<3;round++){for(const m of pool){const already=chosen.find(x=>x.id===m.id)?.qty||0;if(m.price<=left&&already<wish.people&&already<m.stock){chosen.push({id:m.id,qty:1});left-=m.price;if(chosen.length>=Math.min(wish.people*2,6))break}}if(chosen.length>=Math.min(wish.people*2,6))break}const merged=[];for(const x of chosen){const hit=merged.find(y=>y.id===x.id);if(hit)hit.qty++;else merged.push({...x})}return {...wish,items:merged,total:wish.budget-left}}
function aiOpen(){overlay('AI 세트 추천',`<p class="muted">인원, 예산, 취향을 적어 주세요. 현재 재고와 예산을 확인해 조합을 제안합니다.</p><textarea id="ai-prompt" rows="3" placeholder="예: 2명이 2만원으로 먹을 수 있는 음식, 커피는 빼줘">${esc(aiText)}</textarea><button class="primary" data-action="ai-run">맞춤 조합 찾기 →</button><p class="demo-note">현재는 입력 문장을 규칙으로 분석하는 데모입니다. 외부 AI 모델은 아직 연결되지 않았습니다.</p>`)}
function aiRun(){aiText=$('#ai-prompt')?.value.trim()||'';if(!aiText){toast('원하는 조건을 입력해 주세요.');return}aiResult=recommend(aiText);overlay('추천 세트',`<div class="recommend-summary"><strong>${aiResult.people}명 · 예산 ${won(aiResult.budget)}</strong><p>현재 재고에서 ${aiResult.items.length}가지 메뉴를 골랐어요.</p></div>${aiResult.items.length?aiResult.items.map(x=>{const m=active().find(m=>m.id===x.id);return `<div class="mini-item"><span>${esc(m.name)} × ${x.qty}<small>${esc(shop(m.shop).name)}</small></span><strong>${won(m.price*x.qty)}</strong></div>`}).join(''):'<p class="muted">조건에 맞는 조합이 없습니다. 예산이나 조건을 바꿔 주세요.</p>'}<div class="cart-total"><span>추천 합계</span><strong>${won(aiResult.total)}</strong></div><button class="primary" data-action="ai-add" ${!aiResult.items.length?'disabled':''}>추천 메뉴 담기</button><button class="outline-button full" data-action="ai-open">조건 다시 입력</button><p class="demo-note">추천은 규칙 기반 데모이며 실제 AI 모델은 아직 연결되지 않았습니다.</p>`)}
function extractDraft(t){const price=parseKoreanAmount(t),stock=Number(t.match(/(\d+)\s*(개|잔|인분|그릇)/)?.[1]||0);const h=t.match(/(?:오후\s*)?(\d{1,2})\s*시(?:\s*(\d{1,2})\s*분)?/),closing=h?String((Number(h[1])<12&&/오후/.test(t)?Number(h[1])+12:Number(h[1]))).padStart(2,'0')+':'+String(Number(h[2]||0)).padStart(2,'0'):'18:00';let name=t.replace(/\d[\d,]*\s*(?:만|천)?\s*원/g,'').replace(/\d+\s*(?:개|잔|인분|그릇)/g,'').replace(/(?:오후\s*)?\d{1,2}\s*시(?:\s*\d{1,2}\s*분)?/g,'').replace(/(남았고|남았어요|남음|마감해요|마감|오늘|이고|입니다|이에요|이요|에|합니다)/g,' ').replace(/[,.，。]/g,' ').replace(/\s+/g,' ').trim();return {name:name.slice(0,40),price:price||0,stock,closing,shop:$('#product-shop')?.value||'bake',desc:t}}
function makeDraft(){const t=$('#product-phrase')?.value.trim();if(!photo){toast('상품 사진을 먼저 선택해 주세요.');return}if(!t){toast('상품 정보를 말하거나 입력해 주세요.');return}draft=extractDraft(t);draftView()}
function draftView(){overlay('등록 초안 확인',`<p class="muted">추출한 내용을 확인하고 필요한 부분을 고쳐 주세요.</p><img class="draft-photo" src="${photo}" alt="등록할 상품 사진"><form id="draft-form"><label class="form-label">상품 이름<input name="name" required maxlength="40" value="${esc(draft.name)}"></label><div class="form-grid"><label class="form-label">가격 (원)<input name="price" type="number" min="100" required value="${draft.price}"></label><label class="form-label">재고량<input name="stock" type="number" min="0" required value="${draft.stock}"></label></div><label class="form-label">마감시간<input name="closing" type="time" required value="${esc(draft.closing)}"></label><label class="form-label">가게<select name="shop">${shops.map(s=>`<option value="${s.id}" ${s.id===draft.shop?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><button class="primary" type="submit">확인하고 메뉴 등록하기</button></form><p class="demo-note">등록 메뉴는 현재 브라우저에만 저장됩니다.</p>`)}
function edit(id){const m=active().find(x=>x.id===Number(id));if(!m)return;overlay('메뉴 수정',`<form id="edit-form" data-id="${m.id}"><label class="form-label">상품 이름<input name="name" required maxlength="40" value="${esc(m.name)}"></label><div class="form-grid"><label class="form-label">가격 (원)<input name="price" type="number" min="100" required value="${m.price}"></label><label class="form-label">남은 수량<input name="stock" type="number" min="0" required value="${m.stock}"></label></div><label class="form-label">마감시간<input name="closing" type="time" required value="${esc(m.closing||'18:00')}"></label><button class="primary" type="submit">변경 저장</button></form>`)}
function dictate(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('이 브라우저는 음성 인식을 지원하지 않습니다. 내용을 직접 입력해 주세요.');return}recognition?.stop();recognition=new SpeechRecognition();recognition.lang='ko-KR';recognition.interimResults=true;recognition.continuous=false;let finalText=$('#product-phrase')?.value.trim()||'';recognition.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)finalText+=' '+e.results[i][0].transcript;else interim+=e.results[i][0].transcript}const field=$('#product-phrase');if(field)field.value=(finalText+' '+interim).trim()};recognition.onerror=()=>toast('음성 인식이 중단되었습니다. 직접 입력할 수 있습니다.');recognition.onend=()=>{const s=$('#mic-status');if(s)s.textContent='인식된 내용을 확인하고 초안을 만들어 주세요.'};try{recognition.start();$('#mic-status').textContent='듣고 있습니다. 상품 정보를 말씀해 주세요.'}catch{toast('마이크를 시작할 수 없습니다. 직접 입력해 주세요.')}}
function locate(){if(!navigator.geolocation){toast('이 브라우저는 위치 기능을 지원하지 않습니다.');return}navigator.geolocation.getCurrentPosition(p=>{state.location={lat:p.coords.latitude,lng:p.coords.longitude};state.locationStatus='live';persist();render();toast('현재 위치에서 3km 이내 메뉴를 표시합니다.')},()=>toast('위치를 사용할 수 없어 성수동 예시 위치를 유지합니다.'),{enableHighAccuracy:false,timeout:10000,maximumAge:300000})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.classList.contains('overlay-bg'))close();return}const a=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;if(a==='close')close();else if(a==='home'){state.mode='guest';state.tab='feed';render();scrollTo(0,0)}else if(a==='mode'){state.mode=state.mode==='guest'?'owner':'guest';state.tab=state.mode==='owner'?'register':'feed';persist();close();render();scrollTo(0,0)}else if(a==='tab'){state.tab=v;persist();close();render();scrollTo(0,0)}else if(a==='font-up'||a==='font-down'){state.font=Math.max(.85,Math.min(1.35,Math.round((state.font+(a==='font-up'?.1:-.1))*100)/100));persist();render()}else if(a==='speak')pageSpeech();else if(a==='locate')locate();else if(a==='like'){state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];persist();render()}else if(a==='add'){const m=active().find(x=>x.id===id),x=state.cart.find(x=>x.id===id);if(!m||m.stock<=(x?.qty||0)){toast('남은 재고를 확인해 주세요.');return}if(x)x.qty++;else state.cart.push({id,qty:1});persist();render();toast('메뉴를 담았어요.')}else if(a==='cart')cartPage();else if(a==='qty'){const x=state.cart.find(x=>x.id===id),m=active().find(m=>m.id===id);if(!x)return;x.qty+=Number(v);if(x.qty<=0)state.cart=state.cart.filter(y=>y.id!==id);else if(x.qty>m.stock){x.qty=m.stock;toast('남은 재고까지만 담을 수 있어요.')}persist();cartPage()}else if(a==='order')order();else if(a==='route')route(id);else if(a==='shop')shopInfo(v);else if(a==='review')toast('리뷰 작성 기능은 추후 제공됩니다.');else if(a==='ai-open')aiOpen();else if(a==='ai-run')aiRun();else if(a==='ai-add'){for(const x of aiResult.items){const m=active().find(m=>m.id===x.id),inCart=state.cart.find(y=>y.id===x.id);if(m&&m.stock>=(inCart?.qty||0)+x.qty){if(inCart)inCart.qty+=x.qty;else state.cart.push({...x})}}persist();close();render();cartPage()}else if(a==='dictate')dictate();else if(a==='make-draft')makeDraft();else if(a==='edit')edit(id)});
document.addEventListener('input',e=>{if(e.target.id==='feed-search'){const pos=e.target.selectionStart;feedQuery=e.target.value;const list=$('.feed-list');if(list)list.innerHTML=visibleFeed().map(card).join('')||'<div class="empty"><h2>검색 결과가 없어요</h2></div>';e.target.setSelectionRange(pos,pos)}if(e.target.id==='map-search'){mapQuery=e.target.value;const val=mapQuery;render();const inp=$('#map-search');inp.focus();inp.setSelectionRange(val.length,val.length)}});
document.addEventListener('change',e=>{if(e.target.id==='product-photo'){const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('5MB 이하의 JPG, PNG, WebP 사진을 선택해 주세요.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,900/img.width);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);photo=c.toDataURL('image/jpeg',.78);render();toast('사진을 선택했어요.')};img.src=reader.result};reader.readAsDataURL(f)}});
document.addEventListener('submit',e=>{const f=e.target;if(!['draft-form','edit-form'].includes(f.id))return;e.preventDefault();const d=new FormData(f),name=String(d.get('name')||'').trim(),price=Number(d.get('price')),stock=Number(d.get('stock')),closing=String(d.get('closing'));if(!name||!Number.isFinite(price)||price<100||!Number.isInteger(stock)||stock<0)return;if(f.id==='draft-form'){state.menus.unshift({id:Date.now(),shop:d.get('shop'),name,price,stock,closing,image:photo,desc:draft.desc,date:day(),likes:0,sample:false});draft=null;photo=null;close();state.tab='manage';persist();render();toast('오늘 메뉴를 등록했어요.')}else{const m=active().find(x=>x.id===Number(f.dataset.id));if(!m)return;Object.assign(m,{name,price,stock,closing});persist();close();render();toast('메뉴 정보를 저장했어요.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#overlay').innerHTML)close()});
window.addEventListener('storage',e=>{if(e.key==='hangolmok-v2'&&e.newValue){try{state=JSON.parse(e.newValue);render()}catch{}}});
function initMap(){const holder=$('#leaflet-map');if(!holder||!window.L)return;holder.parentElement.classList.add('has-map');if(leafletMap){leafletMap.remove();leafletMap=null}const c=center();leafletMap=L.map(holder,{zoomControl:true,scrollWheelZoom:false}).setView([c.lat,c.lng],15);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(leafletMap);L.circle([c.lat,c.lng],{radius:3000,color:'#47634d',weight:1,fillColor:'#91b48b',fillOpacity:.08}).addTo(leafletMap);L.circleMarker([c.lat,c.lng],{radius:9,color:'#fff',weight:3,fillColor:'#ed6b45',fillOpacity:1}).addTo(leafletMap).bindTooltip('내 위치');visibleMapShops().forEach(s=>L.marker([s.lat,s.lng],{title:s.name}).addTo(leafletMap).on('click',()=>shopInfo(s.id)).bindTooltip(s.name));setTimeout(()=>leafletMap?.invalidateSize(),0)}
render();
